import openpyxl
wb = openpyxl.load_workbook('/tmp/2011-IndiaStateDist.xlsx', read_only=True, data_only=True)
ws = wb['Data']
rows = ws.iter_rows(values_only=True)
header = next(rows)
idx = {name: i for i, name in enumerate(header)}
targets = {'PATNA', 'GAYA', 'NALANDA'}
bihar_rows = []
for r in rows:
    if r[idx['State']] == '10' and r[idx['Level']] == 'DISTRICT' and r[idx['TRU']] == 'Total':
        name = (r[idx['Name']] or '').strip().upper()
        if name in targets:
            bihar_rows.append((name, r[idx['District']], r[idx['No_HH']], r[idx['TOT_P']], r[idx['TOT_M']], r[idx['TOT_F']]))
        else:
            pass
print('Target districts found:')
for t in sorted(bihar_rows):
    print(t)
print()
print('All Bihar districts (check spelling):')
rows2 = ws.iter_rows(values_only=True)
next(rows2)
for r in rows2:
    if r[idx['State']] == '10' and r[idx['Level']] == 'DISTRICT' and r[idx['TRU']] == 'Total':
        print(r[idx['District']], repr(r[idx['Name']]), r[idx['TOT_P']])

